      ms' = MS (mkR (Z_to_bv 64 0xac674) sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 j) (wz n') a2' a3' a4' a5 a6 a7 (Z_to_bv 64 j) s3 s4 s5 s6 s7 s8 (Z_to_bv 64 RSIZE_CLASSES) s10 s11 t3 t4 t5 t6)
              F (Z_to_bv 64 ralloc_slot_entry) fc None m (seg_rom rsegs))
