Lemma rregion_facts_hi : forall st m rid r,
  rmrep st m -> (s_regions st) !! rid = Some r ->
  r_base r + round_up_pg (r_len r) <= 0xc6000 \/ 0xfa000 <= r_base r.
Proof.
